#!/usr/bin/env python3
"""Reproducible faults, memory comparisons and serial soak runs. Offline by default."""
from __future__ import annotations

import argparse
from contextlib import closing
import math
import os
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent))
import continuity_support  # Makes the local kernel and SDK importable under -P.


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    # Private subprocess entry points; all inputs are generated by this harness.
    if args and args[0].startswith("_"):
        root = Path(args[1])
        if args[0] == "_work":
            from continuity_faults import worker
            worker(root, float(args[2]), args[3])
        elif args[0] == "_memory":
            from continuity_memory import worker
            worker(root, bool(int(args[2])), bool(int(args[3])))
        elif args[0] == "_extract":
            from continuity_memory import extraction
            extraction(root, bool(int(args[2])))
        elif args[0] == "_soak":
            from continuity_soak import worker
            worker(root, bool(int(args[2])), bool(int(args[3])))
        else:
            raise ValueError("Unknown worker")
        return 0
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("faults", "memory", "soak"))
    parser.add_argument("--out", type=Path, required=True, help="New, dedicated result directory")
    parser.add_argument("--live", action="store_true", help="Explicit real model calls using SDK_* environment")
    parser.add_argument("--repeats", type=int, default=1)
    parser.add_argument("--max-model-requests", type=int, default=41)
    parser.add_argument("--seconds", type=float, default=60, help="Observed soak duration, excluding downtime")
    parser.add_argument("--interval", type=float, default=1)
    parser.add_argument("--max-cycles", type=int, default=100)
    parser.add_argument("--resume", action="store_true", help="Resume an interrupted soak with its original settings")
    opts = parser.parse_args(args)
    if (not all(math.isfinite(x) and x > 0 for x in (opts.seconds, opts.interval))
            or not 1 <= opts.repeats <= 100 or not 1 <= opts.max_cycles <= 100000
            or not 1 <= opts.max_model_requests <= 100000):
        parser.error("Durations and budgets must be finite and positive (repeats <= 100)")
    if opts.live and opts.mode == "faults":
        parser.error("Fault injection never calls a model")
    if opts.live and not all(os.environ.get(k) for k in ("SDK_MODEL", "SDK_API_KEY")):
        parser.error("Live mode requires SDK_MODEL and SDK_API_KEY; credentials are never printed")
    if opts.mode == "memory" and opts.live and 40 * opts.repeats + 1 > opts.max_model_requests:
        parser.error("Memory matrix exceeds request budget; increase --max-model-requests or reduce --repeats")
    if opts.resume and opts.mode != "soak":
        parser.error("Only soak campaigns support resume")
    root = opts.out.resolve()
    if not opts.resume:
        if root.exists():
            parser.error("Output already exists; choose a new directory (or --resume for an interrupted soak)")
        root.mkdir(parents=True, mode=0o700)
    elif not (root / "campaign.json").is_file():
        parser.error("No campaign to resume")
    from xiaoyu.session_log import SessionWriteLock
    with closing(SessionWriteLock(root / "campaign.owner")):
        if opts.mode == "faults":
            from continuity_faults import run
            result = run(root)
        elif opts.mode == "memory":
            from continuity_memory import run
            result = run(root, live=opts.live, repeats=opts.repeats, max_requests=opts.max_model_requests)
        else:
            from continuity_soak import run
            result = run(root, seconds=opts.seconds, interval=opts.interval, live=opts.live,
                         max_cycles=opts.max_cycles, max_model_requests=opts.max_model_requests, resume=opts.resume)
    print(f"{result['status']}: {root / 'report.json'}")
    return 0 if result["status"] == "pass" else 1


if __name__ == "__main__":
    raise SystemExit(main())
